create table public.plans (
  id uuid primary key default gen_random_uuid(),
  user_id uuid,
  is_demo boolean not null default false,
  title text not null default 'My build',
  answers jsonb not null default '{}'::jsonb,
  plan jsonb not null,
  created_at timestamptz not null default now()
);
grant select, insert, update, delete on public.plans to authenticated;
grant select on public.plans to anon;
grant all on public.plans to service_role;
alter table public.plans enable row level security;
create policy "read own or demo plans" on public.plans for select to anon, authenticated using (is_demo or user_id = auth.uid());
create policy "insert own plans" on public.plans for insert to authenticated with check (user_id = auth.uid() and is_demo = false);
create policy "update own plans" on public.plans for update to authenticated using (user_id = auth.uid()) with check (user_id = auth.uid() and is_demo = false);
create policy "delete own plans" on public.plans for delete to authenticated using (user_id = auth.uid());

create table public.step_progress (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null,
  plan_id uuid not null references public.plans(id) on delete cascade,
  step_id text not null,
  done boolean not null default true,
  updated_at timestamptz not null default now(),
  unique (user_id, plan_id, step_id)
);
grant select, insert, update, delete on public.step_progress to authenticated;
grant all on public.step_progress to service_role;
alter table public.step_progress enable row level security;
create policy "own progress" on public.step_progress for all to authenticated using (user_id = auth.uid()) with check (user_id = auth.uid());

create table public.chat_messages (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null,
  plan_id uuid references public.plans(id) on delete cascade,
  context text not null default 'onboarding',
  role text not null,
  content text not null,
  created_at timestamptz not null default now()
);
grant select, insert, update, delete on public.chat_messages to authenticated;
grant all on public.chat_messages to service_role;
alter table public.chat_messages enable row level security;
create policy "own messages" on public.chat_messages for all to authenticated using (user_id = auth.uid()) with check (user_id = auth.uid());

insert into public.plans (id, user_id, is_demo, title, answers, plan) values ('00000000-0000-0000-0000-000000000001', null, true, 'A booking app for a local yoga studio', $j${"idea": "A booking app for a local yoga studio", "audience": "Students and the studio owner", "needs": "User accounts, a database", "os": "Mac", "ram": "16GB", "comfort": "A little", "domain": "Yes"}$j$::jsonb, $j${"title": "Lotus Booking \u2014 a booking app for a local yoga studio", "summary": "A simple website where students can see the weekly class timetable, book a spot in a class, and cancel if plans change. The studio owner gets a small dashboard to add classes and see who is coming.", "audience": "Students of a small neighbourhood yoga studio, and the studio owner who manages classes.", "features": ["Weekly class timetable anyone can browse", "Student accounts with email sign-in", "Book or cancel a spot in a class", "Class capacity so classes can't be overbooked", "Owner dashboard to add, edit and cancel classes", "Confirmation email after booking"], "userFlow": ["A student opens the website and sees this week's classes", "They pick a class and tap \"Book my spot\"", "If they're new, they create an account with their email", "They get a confirmation and see the class in \"My bookings\"", "The owner sees the booking in their dashboard"], "stack": [{"name": "React + Vite", "role": "The website itself", "why": "The most popular way to build web pages today, so your coding agent knows it inside out and help is easy to find."}, {"name": "Tailwind CSS", "role": "How it looks", "why": "Lets your agent style pages quickly without writing separate design files."}, {"name": "Supabase", "role": "Accounts and data", "why": "Gives you sign-in and a database for bookings with a generous free tier \u2014 no server to manage."}, {"name": "Cloudflare Pages", "role": "Putting it online", "why": "Free, fast hosting that updates automatically every time you save to GitHub."}], "setup": {"modelAdvice": "With 16GB of RAM on your Mac, a model like Qwen2.5-Coder 7B runs comfortably on your own computer through Ollama. It's free and private. If it ever feels slow, you can switch your coding agent to a free cloud model instead \u2014 your code stays yours either way.", "steps": [{"id": "setup-editor", "title": "Install a code editor", "explain": "VS Code is a free app for viewing and editing your project files. Download it from code.visualstudio.com, or install it with Homebrew.", "command": "brew install --cask visual-studio-code", "expected": "==> Installing Cask visual-studio-code\n\ud83c\udf7a  visual-studio-code was successfully installed!"}, {"id": "setup-git", "title": "Install Git", "explain": "Git quietly keeps a history of every change you make, so you can always go back.", "command": "brew install git", "expected": "\ud83c\udf7a  /opt/homebrew/Cellar/git/2.47.0: 1,684 files"}, {"id": "setup-node", "title": "Install Node.js", "explain": "Node lets your computer run the tools that build modern websites.", "command": "brew install node", "expected": "\ud83c\udf7a  /opt/homebrew/Cellar/node/22.11.0"}, {"id": "setup-ollama", "title": "Install Ollama", "explain": "Ollama runs AI models on your own computer, for free.", "command": "brew install ollama && ollama serve", "expected": "Listening on 127.0.0.1:11434"}, {"id": "setup-model", "title": "Download your AI model", "explain": "This downloads a coding model sized for your 16GB machine. It's a few gigabytes, so grab a cup of tea.", "command": "ollama pull qwen2.5-coder:7b", "expected": "pulling manifest\nsuccess"}, {"id": "setup-agent", "title": "Install your coding agent", "explain": "OpenCode is a helper that lives in your terminal. You describe what you want, it writes the code.", "command": "npm install -g opencode-ai", "expected": "added 1 package in 4s"}]}, "build": {"intro": "Paste each prompt into your coding agent, one at a time. Wait for it to finish and check the result before moving on \u2014 small steps make problems easy to fix.", "prompts": [{"id": "build-1", "title": "Create the project", "why": "Starting from a clean, standard template means fewer surprises later.", "prompt": "Create a new React + Vite + TypeScript project called lotus-booking with Tailwind CSS set up. Add a simple home page that says \"Lotus Yoga \u2014 Book your class\". Then tell me the exact command to start it.", "expected": "A new lotus-booking folder, and the page opens at http://localhost:5173"}, {"id": "build-2", "title": "Show the class timetable", "why": "Seeing classes is the heart of the app, so we build it first with sample data.", "prompt": "On the home page, show a weekly timetable of yoga classes grouped by day. Each class shows name, time, teacher and spots left. Use 8 sample classes stored in a local file for now. Make it look calm and friendly on mobile.", "expected": "A list of classes grouped by Monday\u2013Sunday, readable on your phone"}, {"id": "build-3", "title": "Connect accounts and data", "why": "Now we swap sample data for a real database so bookings are saved.", "prompt": "Connect this app to Supabase using environment variables VITE_SUPABASE_URL and VITE_SUPABASE_ANON_KEY. Create tables for classes and bookings, with security rules so students only see their own bookings. Add email sign-in. Give me the SQL to paste into Supabase.", "expected": "A sign-in page works and classes load from your database"}, {"id": "build-4", "title": "Book and cancel", "why": "This is the action students came for.", "prompt": "Add a \"Book my spot\" button on each class. Signed-in students can book once per class, and only if spots are left. Add a \"My bookings\" page where they can cancel.", "expected": "Booking a class lowers the spots left; it appears under My bookings"}, {"id": "build-5", "title": "Owner dashboard", "why": "The owner needs a simple way to run the timetable.", "prompt": "Add an /admin page only the studio owner can open (check an is_owner flag in a profiles table). The owner can add, edit and cancel classes and see the list of who booked each class.", "expected": "Signed in as the owner, you can add a class and see it on the timetable"}]}, "github": {"explainer": ["Git is like a save button with memory \u2014 every time you save, it remembers exactly what changed.", "GitHub is a safe online folder that remembers every version of your project. If your laptop breaks, your work is still there.", "Your hosting provider watches your GitHub folder and puts the newest version online automatically."], "steps": [{"id": "gh-init", "title": "Start tracking your project", "explain": "Tells Git to start remembering changes in this folder.", "command": "cd lotus-booking && git init", "expected": "Initialized empty Git repository in .../lotus-booking/.git/"}, {"id": "gh-commit", "title": "Make your first save", "explain": "Takes a snapshot of everything with a short note about what it is.", "command": "git add . && git commit -m \"First version of Lotus Booking\"", "expected": "[main (root-commit) a1b2c3d] First version of Lotus Booking"}, {"id": "gh-create", "title": "Create your GitHub folder", "explain": "Sign up free at github.com, click \"New repository\", name it lotus-booking and leave it empty. Then connect it:", "command": "git remote add origin https://github.com/YOUR-NAME/lotus-booking.git", "expected": "(no output \u2014 that means it worked)"}, {"id": "gh-push", "title": "Upload to GitHub", "explain": "Sends your saved snapshot up to GitHub.", "command": "git branch -M main && git push -u origin main", "expected": "branch 'main' set up to track 'origin/main'."}]}, "launch": {"options": [{"category": "Hosting", "name": "Cloudflare Pages", "freeTier": "Unlimited visitors, 500 builds/month", "cost": "\u20ac0", "bestFor": "Most small apps", "recommended": true}, {"category": "Hosting", "name": "Netlify", "freeTier": "100GB traffic/month", "cost": "\u20ac0", "bestFor": "Simple sites with forms", "recommended": false}, {"category": "Hosting", "name": "Vercel", "freeTier": "Hobby plan, non-commercial", "cost": "\u20ac0", "bestFor": "Personal projects", "recommended": false}, {"category": "Backend", "name": "Supabase", "freeTier": "500MB database, 50k users", "cost": "\u20ac0", "bestFor": "Accounts + data", "recommended": true}, {"category": "Backend", "name": "PocketBase", "freeTier": "Self-hosted, open source", "cost": "\u20ac0 + server", "bestFor": "Full control", "recommended": false}, {"category": "Domain", "name": "Cloudflare Registrar", "freeTier": "At-cost pricing, no markup", "cost": "~\u20ac10/yr", "bestFor": "Pairs with Cloudflare Pages", "recommended": true}, {"category": "Domain", "name": "Porkbun", "freeTier": "Cheap first year", "cost": "~\u20ac11/yr", "bestFor": "Easy setup", "recommended": false}], "recommendation": "For a small studio, Cloudflare Pages + Supabase costs nothing until you have thousands of students. Buying your domain from Cloudflare keeps everything in one place with no markup.", "steps": [{"id": "launch-connect", "title": "Connect GitHub to Cloudflare Pages", "explain": "In Cloudflare, go to Workers & Pages \u2192 Create \u2192 Pages \u2192 Connect to Git, and choose lotus-booking. Use these build settings:", "command": "Build command: npm run build\nOutput folder: dist", "expected": "Success! Your site is live at lotus-booking.pages.dev"}, {"id": "launch-env", "title": "Add your secret settings", "explain": "Your live site needs the same database details as your computer. Add them under Settings \u2192 Environment variables.", "command": "VITE_SUPABASE_URL=...\nVITE_SUPABASE_ANON_KEY=...", "expected": "Classes load on your live site"}, {"id": "launch-domain", "title": "Add your own domain (optional)", "explain": "Buy lotusyoga.ie (or similar) and add it under Custom domains. Cloudflare sets everything up for you.", "command": "Custom domains \u2192 Set up a domain \u2192 lotusyoga.ie", "expected": "Active \u2014 your app is live at your own address \ud83c\udf89"}]}, "costs": [{"item": "AI model", "amount": 0, "label": "\u20ac0", "note": "Runs on your computer. Never costs money.", "optional": false}, {"item": "Coding agent", "amount": 0, "label": "\u20ac0", "note": "Open source and free forever.", "optional": false}, {"item": "GitHub", "amount": 0, "label": "\u20ac0", "note": "Free for public and private projects.", "optional": false}, {"item": "Hosting", "amount": 0, "label": "\u20ac0 (free tier)", "note": "Only costs money if you need more than 500 updates a month.", "optional": false}, {"item": "Database", "amount": 0, "label": "\u20ac0 (free tier)", "note": "Starts costing ~\u20ac25/month past 500MB or 50,000 users \u2014 far beyond a local studio.", "optional": false}, {"item": "Domain", "amount": 12, "label": "~\u20ac10\u201315/year", "note": "Optional. Renews yearly. You can launch on a free .pages.dev address instead.", "optional": true}]}$j$::jsonb);